function clean(v,lang){ let s=String(v||'').trim(); const fence=String.fromCharCode(96).repeat(3); if(s.startsWith(fence)){ s=s.slice(3).replace(new RegExp('^'+(lang||'json'),'i'),'').trim(); } if(s.endsWith(fence)) s=s.slice(0,-3).trim(); return s; } function parse(v){ if(typeof v==='object')return v; return JSON.parse(clean(v,'json')); }
let parsed; try{ parsed=parse($json.output||$json.text||$json); }catch(e){ return [{json:{state:{iteration:1,max_loops:3,invalid_streak:0,history:[]},hypothesis:'Không đọc được output SQL Writer',sql:'',sql_valid:false,guardrail_reason:'JSON không hợp lệ: '+e.message}}]; }
let sql=clean(parsed.sql||'','sql').replace(/;\s*$/,''); const reasons=[];
if(!/^(SELECT|WITH)\b/i.test(sql)) reasons.push('Query phải bắt đầu bằng SELECT hoặc WITH');
if(/\b(INSERT|UPDATE|DELETE|DROP|CREATE|MERGE|ALTER|TRUNCATE|CALL|EXECUTE|GRANT|REVOKE)\b/i.test(sql)) reasons.push('Có từ khóa ghi/xóa bị cấm');
if(sql.includes(';')) reasons.push('Không cho phép nhiều statement');
if(/SELECT\s+\*/i.test(sql)) reasons.push('Không cho phép SELECT *');
const lm=sql.match(/\bLIMIT\s+(\d+)\b/i); if(!lm) reasons.push('Thiếu LIMIT'); else if(Number(lm[1])>200) reasons.push('LIMIT vượt 200');
const tick=String.fromCharCode(96); const parts=sql.split(tick); const refs=parts.filter((_,i)=>i%2===1); if(refs.some(r=>!r.startsWith('tmdatabase.dm_base_crm.')&&r!=='tmdatabase.dm_daily_brief.dim_course')) reasons.push('Tham chiếu bảng ngoài allowlist');
return [{json:{state:parsed.state||{},hypothesis:parsed.hypothesis||'',rationale:parsed.rationale||'',sql,sql_valid:reasons.length===0,guardrail_reason:reasons.join('; ')}}];

