return [
  {
    json: {
      // =========================
      // BigQuery
      // =========================
      gcp_project: 'tmdatabase',
      bq_dataset: 'dm_base_crm',
      config_dataset: 'tmdatabase.dm_daily_brief',

      // =========================
      // Timezone
      // =========================
      timezone: 'Asia/Ho_Chi_Minh',

      // =========================
      // Thresholds
      // =========================
      thresholds: {
        // KPI
        kpi_normal_band_pct: 20,
        cvr_drop_pp: 5,

        // Warning
        warning_drop_pct: 20,
        warning_zero_lead_days: 5,

        warning_pending_days: 3,
        warning_pending_min_count: 5,

        warning_open_deal_days: 14,
        warning_open_deal_min: 5,

        // Focus Group
        focus_positive_pct: 15,
        focus_negative_pct: -15,

        // Minimum base volume
        min_base_volume: 3,

        // Data Health
        unmapped_alert_min: 1,
      },

      // =========================
      // Limits
      // =========================
      limits: {
        // Daily
        top_course_per_bu: 5,
        top_utm_rows: 8,
        max_warning_rows: 12,

        // Weekly
        top_utm_rows_weekly: 12,
        weekly_min_content_leads: 3,

        // Root Cause Analyst
        rca_max_loops: 3,
        rca_max_rows: 200,
      },

      // =========================
      // OpenAI
      // =========================
      openai_model: 'gpt-4.1',
    },
  },
];

function vnParts(d) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Ho_Chi_Minh',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'short',
  });

  const parts = fmt.formatToParts(d);

  const get = (type) => {
    return parts.find((p) => p.type === type).value;
  };

  return {
    y: get('year'),
    m: get('month'),
    d: get('day'),
    weekday: get('weekday'),
  };
}


function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(
    /[xy]/g,
    (c) => {
      const r = (Math.random() * 16) | 0;

      return (
        c === 'x'
          ? r
          : (r & 3) | 8
      ).toString(16);
    }
  );
}


// ==============================
// Week key theo tuần T2 → CN
// Ví dụ: 2026-M8W5
// ==============================

function getMonthWeekKey(date) {
  const vn = vnParts(date);

  const year = Number(vn.y);
  const month = Number(vn.m);
  const day = Number(vn.d);

  // Ngày đầu tiên của tháng
  const firstDay = new Date(
    Date.UTC(year, month - 1, 1)
  );

  // JS:
  // Sun = 0
  // Mon = 1
  // Tue = 2
  // ...
  //
  // Chuyển thành:
  // Mon = 0
  // Tue = 1
  // ...
  // Sun = 6
  const firstWeekday =
    (firstDay.getUTCDay() + 6) % 7;

  const weekOfMonth = Math.ceil(
    (day + firstWeekday) / 7
  );

  return `${year}-M${month}W${weekOfMonth}`;
}


// ==============================
// DATE
// ==============================

// CHẠY THẬT
// const now = new Date();

// TEST — comment dòng trên và mở một dòng bên dưới
const now = new Date('2026-08-24T08:00:00+07:00');
// const now = new Date('2026-08-25T08:00:00+07:00');
// const now = new Date('2026-08-26T08:00:00+07:00');
// const now = new Date('2026-08-27T08:00:00+07:00');
// const now = new Date('2026-08-28T08:00:00+07:00');
// const now = new Date('2026-08-29T08:00:00+07:00');
// const now = new Date('2026-08-30T08:00:00+07:00');


// ==============================
// Ngày hiện tại theo VN
// ==============================

const todayVN = vnParts(now);


// ==============================
// Map thứ → report_day
// ==============================

const weekdayMap = {
  Mon: 2,
  Tue: 3,
  Wed: 4,
  Thu: 5,
  Fri: 6,
  Sat: 7,
  Sun: 0,
};

const reportDay =
  weekdayMap[todayVN.weekday];

const isSaturday =
  todayVN.weekday === 'Sat';

const isSunday =
  todayVN.weekday === 'Sun';


// ==============================
// Ngày báo cáo = hôm qua
// ==============================

const yesterdayDate = new Date(
  now.getTime() - 86400000
);

const yVN = vnParts(yesterdayDate);

const reportDate =
  `${yVN.y}-${yVN.m}-${yVN.d}`;


// ==============================
// Tên thứ
// ==============================

const dayNames = {
  0: 'Chủ Nhật',
  2: 'Thứ Hai',
  3: 'Thứ Ba',
  4: 'Thứ Tư',
  5: 'Thứ Năm',
  6: 'Thứ Sáu',
  7: 'Thứ Bảy',
};


// ==============================
// Focus title
// ==============================

const focusTitles = {
  2: 'MARKETING DAY 1 ALERT',
  3: 'MARKETING DAY 2 & BRAND ALERT',
  4: 'EXECUTIVE EDUCATION ALERT',
  5: 'DATA SCHOOL ALERT',
  6: 'TM AI ALERT',
  7: 'FLEXIBLE COMBO & B2B TRAINING ALERT',
};


// ==============================
// Week key
// ==============================

const weekKey =
  getMonthWeekKey(now);


// ==============================
// Output
// ==============================

return [
  {
    json: {
      run_id: uuidv4(),

      report_date: reportDate,
      report_day: reportDay,

      is_saturday: isSaturday,
      is_sunday: isSunday,

      report_mode: isSunday
        ? 'sunday'
        : isSaturday
          ? 'weekly'
          : 'daily',

      weekday_label:
        dayNames[reportDay] || '',

      focus_title:
        focusTitles[reportDay] || '',

      week_key: weekKey,

      // Chỉ để tiện kiểm tra khi test
      test_today:
        `${todayVN.y}-${todayVN.m}-${todayVN.d}`,
    },
  },
];

const cfg = $('Config').first().json;
const rd = $('Resolve Day').first().json;

// ============================================================
// HELPERS
// ============================================================

function rows(name) {
  return $(name).all().map(item => item.json);
}

function toBool(value) {
  return (
    value === true ||
    String(value).toLowerCase() === 'true'
  );
}

function toNumber(value, fallback = 0) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function countFlags(row) {
  const flagKeys = [
    'flag_lead_drop',
    'flag_deal_drop',
    'flag_no_lead',
    'flag_pending',
    'flag_stale_open',
  ];

  return flagKeys.reduce(
    (count, key) =>
      count + (toBool(row[key]) ? 1 : 0),
    0
  );
}

function normalizeWarning(row) {
  return {
    course_type: row.course_type,
    course_name: row.course_name,

    warning_count: countFlags(row),

    lead_drop: toBool(row.flag_lead_drop)
      ? {
          current: row.lead_per_day_now,
          previous: row.lead_per_day_prev,
          delta_pct: row.lead_delta_pct,
        }
      : null,

    won_drop: toBool(row.flag_deal_drop)
      ? {
          current: row.deal_per_day_now,
          previous: row.deal_per_day_prev,
          delta_pct: row.deal_delta_pct,
        }
      : null,

    no_lead: toBool(row.flag_no_lead)
      ? {
          days: row.days_no_lead,
          last_lead_date: row.last_lead_date,
        }
      : null,

    pending: toBool(row.flag_pending)
      ? {
          count: row.pending_leads,
        }
      : null,

    stale_open: toBool(row.flag_stale_open)
      ? {
          count: row.stale_open_deals,
        }
      : null,
  };
}

function prepareWarnings(rawRows) {
  return rawRows
    .filter(row => countFlags(row) > 0)
    .sort((a, b) => {
      const warningDiff =
        countFlags(b) - countFlags(a);

      if (warningDiff !== 0) {
        return warningDiff;
      }

      const leadA = toNumber(
        a.lead_delta_pct,
        999999
      );

      const leadB = toNumber(
        b.lead_delta_pct,
        999999
      );

      if (leadA !== leadB) {
        return leadA - leadB;
      }

      return (
        toNumber(b.days_no_lead) -
        toNumber(a.days_no_lead)
      );
    })
    .slice(
      0,
      cfg.limits.max_warning_rows
    )
    .map(normalizeWarning);
}

function buildNoLeadSummary(rawRows) {
  const sorted = [...rawRows].sort(
    (a, b) =>
      toNumber(b.days_no_lead) -
      toNumber(a.days_no_lead)
  );

  const tenPlus = sorted.filter(
    row =>
      toNumber(row.days_no_lead) >= 10
  );

  return {
    total_no_lead_yesterday:
      rawRows.length,

    total_10_plus_days:
      tenPlus.length,

    top_5:
      tenPlus.slice(0, 5),
  };
}

// ============================================================
// BASE VALUES
// ============================================================

const isSaturday = toBool(
  rd.is_saturday
);

const isSunday = toBool(
  rd.is_sunday
);

const q1 =
  $('Q1 KPI - Overall').first()?.json ||
  {};

// ============================================================
// REPORT DATE VALIDATION
// ============================================================

if (
  q1.report_date &&
  rd.report_date &&
  String(q1.report_date) !==
    String(rd.report_date)
) {
  throw new Error(
    `REPORT_DATE_MISMATCH: Resolve Day=${rd.report_date}, Q1=${q1.report_date}`
  );
}

// ============================================================
// BASE PAYLOAD
// ============================================================

let payload = {
  run_id: rd.run_id,

  report_date:
    rd.report_date,

  weekday_label:
    rd.weekday_label,

  focus_title:
    rd.focus_title,

  report_mode:
    rd.report_mode,

  is_saturday:
    isSaturday,

  is_sunday:
    isSunday,
};

// ============================================================
// SATURDAY
// ============================================================

if (isSaturday) {
  const courses =
    rows('Q7 Weekly Performance');

  const content =
    rows('Q7 Content Performance');

  const warningRaw =
    rows('Q7 Warning Snapshot');

  const healthRows =
    rows('Q7 Weekly Data Health');

  // ----------------------------
  // Weekly warnings
  // ----------------------------

  const warnings =
    prepareWarnings(warningRaw);

  // ----------------------------
  // Content with tracking
  // ----------------------------

  const tracked =
    content.filter(row => {
      const utmContent =
        String(
          row.utm_content || ''
        ).trim();

      return (
        utmContent !== '' &&
        utmContent !== '(not set)'
      );
    });

  // ----------------------------
  // Top content by leads
  // ----------------------------

  const contentTopLeads =
    [...tracked]
      .sort(
        (a, b) =>
          toNumber(b.n_leads) -
          toNumber(a.n_leads)
      )
      .slice(0, 5);

  // ----------------------------
  // Top content by CVR
  // ----------------------------

  const contentTopCvr =
    [...tracked]
      .filter(row => {
        return (
          toNumber(row.n_leads) >=
            toNumber(
              cfg.limits
                .weekly_min_content_leads
            ) &&
          row.conversion_rate !==
            null &&
          row.conversion_rate !==
            undefined
        );
      })
      .sort((a, b) => {
        const cvrDiff =
          toNumber(
            b.conversion_rate
          ) -
          toNumber(
            a.conversion_rate
          );

        if (cvrDiff !== 0) {
          return cvrDiff;
        }

        return (
          toNumber(b.n_leads) -
          toNumber(a.n_leads)
        );
      })
      .slice(0, 5);

  // ----------------------------
  // Strongest course
  // ----------------------------

  const strongestCourse =
    [...courses]
      .sort((a, b) => {
        const wonDiff =
          toNumber(
            b.won_this_week
          ) -
          toNumber(
            a.won_this_week
          );

        if (wonDiff !== 0) {
          return wonDiff;
        }

        const cvrDiff =
          toNumber(
            b.conversion_rate_this_week,
            -1
          ) -
          toNumber(
            a.conversion_rate_this_week,
            -1
          );

        if (cvrDiff !== 0) {
          return cvrDiff;
        }

        return (
          toNumber(
            b.leads_this_week
          ) -
          toNumber(
            a.leads_this_week
          )
        );
      })[0] || null;

  // ----------------------------
  // Weakest course
  // ----------------------------

  const weakestCourse =
    [...courses]
      .sort((a, b) => {
        const wonDiff =
          toNumber(
            a.won_this_week
          ) -
          toNumber(
            b.won_this_week
          );

        if (wonDiff !== 0) {
          return wonDiff;
        }

        const cvrDiff =
          toNumber(
            a.conversion_rate_this_week,
            999
          ) -
          toNumber(
            b.conversion_rate_this_week,
            999
          );

        if (cvrDiff !== 0) {
          return cvrDiff;
        }

        return (
          toNumber(
            a.lead_delta_pct,
            999
          ) -
          toNumber(
            b.lead_delta_pct,
            999
          )
        );
      })[0] || null;

  // ----------------------------
  // Data health
  // ----------------------------

  const unmappedTotal =
    healthRows.reduce(
      (sum, row) =>
        sum + toNumber(row.n),
      0
    );

  // ----------------------------
  // Saturday payload
  // ----------------------------

  payload = {
    ...payload,

    weekly_performance:
      courses,

    strongest_course:
      strongestCourse,

    weakest_course:
      weakestCourse,

    content_top_leads:
      contentTopLeads,

    content_top_cvr:
      contentTopCvr,

    utm_weekly:
      content,

    warnings,

    data_health: {
      unmapped_total:
        unmappedTotal,

      show_alert:
        unmappedTotal >=
        toNumber(
          cfg.thresholds
            .unmapped_alert_min
        ),

      rows:
        healthRows,
    },
  };
}

// ============================================================
// DAILY: MONDAY → FRIDAY
// ============================================================

else {
  const q0 =
    rows('Q0 Data Health');

  const q2 =
    rows('Q2 Breakdown');

  const q3 =
    rows('Q3 UTM Daily');

  const q4Raw =
    rows('Q4 No-Lead Courses');

  const q5Raw =
    rows('Q5 Warning Scan');

  const q6 =
    rows('Q6 Focus Group1');

  // ----------------------------
  // Warnings
  // ----------------------------

  const warnings =
    prepareWarnings(q5Raw);

  // ----------------------------
  // No-lead summary
  // ----------------------------

  const noLeadSummary =
    buildNoLeadSummary(q4Raw);

  // ----------------------------
  // Data health
  // ----------------------------

  const unmappedTotal =
    q0.reduce(
      (sum, row) =>
        sum + toNumber(row.n),
      0
    );

  // ----------------------------
  // Daily payload
  // ----------------------------

  payload = {
    ...payload,

    kpi:
      q1,

    breakdown:
      q2,

    utm_daily:
      q3,

    no_lead_courses:
      noLeadSummary,

    warnings,

    focus_group:
      q6,

    data_health: {
      unmapped_total:
        unmappedTotal,

      show_alert:
        unmappedTotal >=
        toNumber(
          cfg.thresholds
            .unmapped_alert_min
        ),

      rows:
        q0,
    },
  };
}

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: payload,
  },
];
